package limiter

type Counter struct {
	remaining int
}

func New(limit int) *Counter {
	return &Counter{remaining: limit}
}

func (c *Counter) Allow() bool {
	if c.remaining > 0 {
		c.remaining--
		return true
	}
	return false
}

package server

import "evaltask/internal/limiter"

type Router struct {
	lim   *limiter.Counter
}

func NewRouter(limit int) *Router {
	l := limiter.New(limit)
	return &Router{lim: l}
}

func (r *Router) Handle() int {
	if r.lim.Allow() {
		return 200
	}
	return 429
}
